package hu.boltseged.label;
import hu.boltseged.shipment.*; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="shipment_labels") public class ShipmentLabel { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shipment_id",nullable=false) private Shipment shipment; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="package_id") private ShipmentPackage shipmentPackage; private String storageKey,fileName,contentType,documentType; private Instant createdAt; protected ShipmentLabel(){} public ShipmentLabel(Shipment s,ShipmentPackage p,String key,String name,String type,String documentType){id=UUID.randomUUID();shipment=s;shipmentPackage=p;storageKey=key;fileName=name;contentType=type;this.documentType=documentType;createdAt=Instant.now();} public UUID getId(){return id;} public Shipment getShipment(){return shipment;} public String getStorageKey(){return storageKey;} public String getFileName(){return fileName;} public String getContentType(){return contentType;} }
